rule.definition:
a!localVariables(
  local!recipient: if(
    contains(
      {
        #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4577779",
        #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4458947",
        #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4458895",
        #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4578520",
        #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4578617",
        #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3935295",
        #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3930284",
        #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4967023"
      },
      tointeger(ri!statusId)
    ),
    #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4718496",
    if(
      contains(
        {
          #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4458889",
          #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4458932",
          #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4578354",
          #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3935288",
          #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3927661",
          #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4966786"
        },
        tointeger(ri!statusId)
      ),
      ri!candidateEmail,
      null
    )
  ),
  local!recipientsGroups: if(
    and(
      #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(local!recipient),
      contains(
        {
          #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4489118",
          #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4494074",
          #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4183431"
        },
        tointeger(ri!statusId)
      )
    ),
    #"SYSTEM_SYSRULES_forEach"(
      items: if(
        #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!selectedGroup),
        ri!recipients,
        if(
          #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!selectedBuReviewer),
          ri!selectedBuReviewer,
          ri!selectedGroup
        )
      ),
      expression: if(
        contains(
          {
            "HR Director",
            "DPP Operation Editors",
            ri!selectedBuReviewer,
            ri!selectedGroup,
          },
          tostring(fv!item)
        ),
        fv!item,
        clean(stripwith(fv!item," "))
      )
    ),
    null
  ),
  local!groups: if(
    #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(local!recipientsGroups),
    a!flatten(
      #"SYSTEM_SYSRULES_forEach"(
        items: local!recipientsGroups,
        expression: a!groupsByName(#"_a-0000e676-ab43-8000-9bf5-011c48011c48_3085024"(fv!item))
      )
    ),
    null
  ),
  local!users: if(
    #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(local!groups),
    #"SYSTEM_SYSRULES_forEach"(
      items: local!groups,
      expression: a!groupMembers(fv!item)
    ),
    null
  ),
  local!recipients:if(
    #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(local!groups),
    a!flatten(
      #"SYSTEM_SYSRULES_forEach"(
        items: local!users,
        expression: property(fv!item,"data",null)
      )
    ),
    null
  ),  
  if(
    ri!selectedGroup = #"_a-0000e825-ace1-8000-9c24-011c48011c48_6801187",
    ri!selectedBuReviewer,
    if(
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(local!recipient),
      toemailrecipient(toemailaddress(local!recipient)),
      toemailrecipient(toemailaddress(local!recipients))
    )
  )
)
